    #[test]
    fn set_padding_affects_child_position() {
        let mut layout = Layout::new();
        let child = layout.new_leaf(Style {
            size: Size {
                width: length(50.0),
                height: length(50.0),
            },
            ..Default::default()
        });
        let root = layout.new_with_children(
            Style {
                display: Display::Flex,
                size: Size {
                    width: length(200.0),
