        let child = layout.new_with_children(
            Style {
                display: Display::Flex,
                size: Size {
                    width: length(100.0),
                    height: length(50.0),
                },
                padding: taffy::geometry::Rect {
                    top: length(5.0),
                    right: length(5.0),
                    bottom: length(5.0),
