        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: wgpu::CommandEncoder,
        surface_texture: &wgpu::SurfaceTexture,
    ) -> Result<CapturedFrame, ScreenshotError> {
        self.screenshot_capture.take_screenshot(
            device,
            queue,
            encoder,
            surface_texture,
            self.surface_format,
        )
    }
}

