    /// Returns a measure function for `Layout::compute` that uses the text
    /// pipeline to resolve intrinsic sizes for text-bearing leaves.
    ///
    /// A layout node participates in text measurement when its
    /// `AkarNodeContext::text_buffer_id` is non-zero and refers to a buffer
    /// previously created via `TextPipeline::set_text`. Non-text nodes resolve
    /// to `Size::ZERO`.
    pub fn default_measure_fn(
        &mut self,
    ) -> impl FnMut(
        Size<Option<f32>>,
        Size<AvailableSpace>,
        taffy::NodeId,
        Option<&mut AkarNodeContext>,
        &Style,
    ) -> Size<f32> {
        move |known_dimensions, available_space, _node, context, _style| {
            let Some(ctx) = context else {
                return Size::ZERO;
            };
            if ctx.text_buffer_id == 0 {
                return Size::ZERO;
            }

            let result = self.text_pipeline.measure_with_metadata(
                ctx.text_buffer_id,
                TextMeasureInput {
                    known_width: known_dimensions.width,
                    known_height: known_dimensions.height,
                    available_width: match available_space.width {
                        AvailableSpace::Definite(w) => Some(w),
                        AvailableSpace::MinContent => Some(0.0),
                        AvailableSpace::MaxContent => None,
                    },
                },
            );

            Size {
                width: result.width,
                height: result.height,
            }
        }
    }
}

