/// Per-node context attached to a Taffy leaf through `Tree::new_leaf_with_context`.
///
/// `AkarCore::default_measure_fn` reads `text_buffer_id` to resolve intrinsic
/// sizes for text-bearing leaves. A `text_buffer_id` of 0 means the node has
/// no text and contributes `Size::ZERO`. Non-zero ids refer to a buffer the
/// caller previously created via `TextPipeline::set_text`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct AkarNodeContext {
    pub text_buffer_id: u64,
}

impl AkarNodeContext {
    pub const fn text(buffer_id: u64) -> Self {
        Self {
            text_buffer_id: buffer_id,
        }
    }

    pub const fn empty() -> Self {
        Self {
            text_buffer_id: 0,
        }
    }
}

