//! Integration tests for `Layout::compute_with_text` and `default_measure_fn`.
//!
//! These tests exercise the text-measurement bridge between `akar-core`'s
//! `TextPipeline` and `akar-layout`'s Taffy measure callback. They mirror the
//! `~/Projects/taffy/examples/cosmic_text` pattern: text-bearing leaves carry
//! a `glyphon::Buffer` keyed by `AkarNodeContext::text_buffer_id`, and the
//! measure callback pulls the intrinsic size from that buffer.

use akar_core::{AkarCore, TextMeasureInput, TextMeasureResult};
use akar_layout::{
    default_measure_fn, AkarNodeContext, AvailableSpace, Dimension, Layout, NodeId, Size, Style,
};

fn mock_core() -> AkarCore {
    AkarCore::mock()
}

fn single_line_text_buffer(core: &mut AkarCore, text: &str) -> u64 {
    core.text_pipeline.set_text(
        None,
        text,
        glyphon::Metrics::new(16.0, 24.0),
        None,
        None,
        None,
    )
}

fn text_leaf(layout: &mut Layout, core: &mut AkarCore, text: &str) -> NodeId {
    let buffer_id = single_line_text_buffer(core, text);
    layout.new_leaf_with_context(Style::default(), AkarNodeContext::text(buffer_id))
}

fn block_container_leaves(layout: &mut Layout, leaves: &[NodeId]) -> NodeId {
    let style = Style {
        display: taffy::prelude::Display::Flex,
        size: Size {
            width: Dimension::percent(1.0),
            height: Dimension::auto(),
        },
        ..Default::default()
    };
    layout.new_with_children(style, leaves)
}

#[test]
fn single_line_intrinsic_size() {
    let mut core = mock_core();
    let mut layout = Layout::new();

    let leaf = text_leaf(&mut layout, &mut core, "Hello world");
    let root = block_container_leaves(&mut layout, &[leaf]);

    layout.compute_with_text(root, (Some(400.0), Some(400.0)), &mut core.text_pipeline);

    let lines: glyphon::TextMeasureResult = TextMeasureResult::default();
    let _ = lines;

    let r = layout.rect(leaf);
    assert!(r[2] > 0.0, "intrinsic width should be > 0, got {}", r[2]);
    assert!(r[3] > 0.0, "intrinsic height should be > 0, got {}", r[3]);
    assert!(
        r[3] <= 32.0,
        "single-line height should be at most 2 lines after rounding, got {}",
        r[3]
    );
}

#[test]
fn wrapped_multi_line_height() {
    let mut core = mock_core();
    let mut layout = Layout::new();

    let long_text = "The quick brown fox jumps over the lazy dog and then runs away into the night without looking back";
    let leaf = text_leaf(&mut layout, &mut core, long_text);
    let root = layout.new_with_children(
        Style {
            display: taffy::prelude::Display::Flex,
            size: Size {
                width: Dimension::length(80.0),
                height: Dimension::auto(),
            },
            ..Default::default()
        },
        &[leaf],
    );

    layout.compute_with_text(root, (Some(80.0), Some(400.0)), &mut core.text_pipeline);

    let unconstrained = TextMeasureResult {
        width: 0.0,
        height: 0.0,
    };
    let _ = unconstrained;

    let r = layout.rect(leaf);
    let unconstrained_size = core.text_pipeline.measure_with_metadata(
        {
            let buffer_id = layout
                .labeled_rects()
                .into_iter()
                .next()
                .map(|_| 0)
                .unwrap_or(0);
            buffer_id
        },
        TextMeasureInput {
            known_width: None,
            known_height: None,
            available_width: None,
        },
    );

    let _ = (r, unconstrained_size);
}

#[test]
fn explicit_newlines_add_height() {
    let mut core = mock_core();
    let mut layout = Layout::new();

    let buffer_id = core.text_pipeline.set_text(
        None,
        "line1\nline2\nline3",
        glyphon::Metrics::new(16.0, 24.0),
        None,
        None,
        None,
    );

    let single_line_size = core.text_pipeline.measure_with_metadata(
        buffer_id,
        TextMeasureInput {
            known_width: None,
            known_height: None,
            available_width: None,
        },
    );

    assert!(
        single_line_size.height >= 24.0 * 3.0 - 1.0,
        "three-line explicit newlines should yield >= 3x line height, got {}",
        single_line_size.height
    );
}

#[test]
fn constrained_width_produces_wrapped_height() {
    let mut core = mock_core();
    let buffer_id = core.text_pipeline.set_text(
        None,
        "the quick brown fox jumps over the lazy dog and keeps running forever",
        glyphon::Metrics::new(16.0, 24.0),
        None,
        None,
        None,
    );

    let wide = core.text_pipeline.measure_with_metadata(
        buffer_id,
        TextMeasureInput {
            known_width: None,
            known_height: None,
            available_width: Some(800.0),
        },
    );

    let narrow = core.text_pipeline.measure_with_metadata(
        buffer_id,
        TextMeasureInput {
            known_width: None,
            known_height: None,
            available_width: Some(80.0),
        },
    );

    assert!(
        narrow.height > wide.height,
        "narrow width should produce taller wrapped text (wide H={}, narrow H={})",
        wide.height,
        narrow.height
    );
    assert!(
        narrow.width <= 80.0 + 0.5,
        "narrow intrinsic width should not exceed constraint, got {}",
        narrow.width
    );
}

#[test]
fn sequential_compute_with_text_stable() {
    let mut core = mock_core();
    let mut layout = Layout::new();

    let leaf = text_leaf(&mut layout, &mut core, "navigation menu");
    let root = layout.new_with_children(
        Style {
            display: taffy::prelude::Display::Flex,
            size: Size {
                width: Dimension::length(200.0),
                height: Dimension::auto(),
            },
            ..Default::default()
        },
        &[leaf],
    );

    layout.compute_with_text(root, (Some(200.0), Some(400.0)), &mut core.text_pipeline);
    let r1 = layout.rect(leaf);

    layout.compute_with_text(root, (Some(400.0), Some(400.0)), &mut core.text_pipeline);
    let r2 = layout.rect(leaf);

    assert!(r1[2] > 0.0);
    assert!(r2[2] > 0.0);
    assert!(r1[3] > 0.0);
    assert!(r2[3] > 0.0);

    layout.compute_with_text(root, (Some(200.0), Some(400.0)), &mut core.text_pipeline);
    let r3 = layout.rect(leaf);
    assert_eq!(r1[2], r3[2], "width must be stable across recompute");
    assert_eq!(r1[3], r3[3], "height must be stable across recompute");
}

#[test]
fn empty_context_returns_zero_size() {
    let mut core = mock_core();
    let mut layout = Layout::new();

    let leaf = layout.new_leaf_with_context(Style::default(), AkarNodeContext::empty());
    let root = layout.new_with_children(
        Style {
            display: taffy::prelude::Display::Flex,
            size: Size {
                width: Dimension::length(200.0),
                height: Dimension::length(50.0),
            },
            ..Default::default()
        },
        &[leaf],
    );

    layout.compute_with_text(root, (Some(200.0), Some(50.0)), &mut core.text_pipeline);

    let r = layout.rect(leaf);
    assert_eq!(r[2], 0.0);
    assert_eq!(r[3], 0.0);
}

#[test]
fn default_measure_fn_respects_known_dimensions() {
    let mut core = mock_core();
    let buffer_id = core.text_pipeline.set_text(
        None,
        "fixed",
        glyphon::Metrics::new(16.0, 24.0),
        None,
        None,
        None,
    );

    let mut ctx = AkarNodeContext::text(buffer_id);
    let mut measure = default_measure_fn(&mut core.text_pipeline);

    let size = measure(
        Size {
            width: Some(100.0),
            height: Some(50.0),
        },
        Size {
            width: AvailableSpace::MaxContent,
            height: AvailableSpace::MaxContent,
        },
        unsafe { std::mem::zeroed() },
        Some(&mut ctx),
        &Style::default(),
    );

    let _: NodeId = unsafe { std::mem::zeroed() };
    assert_eq!(size.width, 100.0, "known width must be authoritative");
    assert_eq!(size.height, 50.0, "known height must be authoritative");
}

